import subprocess, gzip
items={
'Cloaca':'https://www.ncbi.nlm.nih.gov/geo/download/?acc=GSM8426946&format=file&file=GSM8426946%5FAxolotl%5FCloaca%5FFragments%2Ebed%2Egz',
'Stomach':'https://www.ncbi.nlm.nih.gov/geo/download/?acc=GSM8426973&format=file&file=GSM8426973%5FAxolotl%5FStomach%5FFragments%2Ebed%2Egz',
}
for tissue,url in items.items():
    p=subprocess.Popen(['curl','-L','-s',url], stdout=subprocess.PIPE)
    out=open(f'galaxy_refs/{tissue}.chr1p_1.lt100k.bed','w')
    try:
        z=gzip.GzipFile(fileobj=p.stdout)
        for raw in z:
            line=raw.decode(errors='replace')
            f=line.rstrip('\\n').split('\\t')
            if len(f)<3: continue
            if f[0]"'!='"'chr1p_1':
                continue
            if int(f[1]) >= 100000:
                break
            out.write(line)
    finally:
        out.close()
        p.terminate()
        try: p.wait(timeout=2)
        except Exception: p.kill()
PY
